/**
 * Story 458 — a form control built from other form controls passes its child's validity up: the
 * same flags and message, anchored where the browser should point. A `ValidityState`'s flags are
 * getters on its prototype, so they are copied out by name.
 */

const FLAGS = [
    'valueMissing', 'typeMismatch', 'patternMismatch', 'tooLong', 'tooShort',
    'rangeUnderflow', 'rangeOverflow', 'stepMismatch', 'badInput', 'customError',
] as const satisfies readonly (keyof ValidityStateFlags)[];

/** A form control whose validity a parent control can take over. */
export interface ValidityChild {
    readonly validity: ValidityState;
    readonly validationMessage: string;
    /** The element the browser focuses and points its message at. */
    readonly validationAnchor: HTMLElement;
    checkValidity(): boolean;
}

/** Set `internals` to `child`'s validity, or valid when there is no invalid child. */
export function takeValidity(internals: ElementInternals, child: ValidityChild | null): void {
    if (!child || child.checkValidity()) {
        internals.setValidity({});
        return;
    }
    const flags: ValidityStateFlags = {};
    for (const flag of FLAGS) if (child.validity[flag]) flags[flag] = true;
    internals.setValidity(flags, child.validationMessage, child.validationAnchor);
}
