import stylesText from './amount-input.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { applyPreset, roundAmount, stepAmount, type AmountUnit } from '../../../../utils/amount-steps.js';
import { unitLabel } from '../../../../utils/line-view.js';
import { createAmountChangeEvent } from '../../health-events.js';

const styles = cssStyleSheet(stylesText);

const PRESETS = [0.5, 1.5, 2] as const;

const template = document.createElement('template');
template.innerHTML = `
    <div class="stepper">
        <button type="button" class="step" data-dir="-1" aria-label="Less">−</button>
        <input class="amount" inputmode="decimal" autocomplete="off" aria-label="Amount">
        <span class="unit"></span>
        <button type="button" class="step" data-dir="1" aria-label="More">+</button>
    </div>
    <div class="presets" hidden>
        ${PRESETS.map((f) => `<button type="button" class="preset" data-factor="${f}">x${f}</button>`).join('')}
    </div>
`;

/**
 * Story 420 — every amount field in the nutrition area (418): `−` input `+` on one line, stepping
 * through the unit's step list (419 review), optional ×0.5/×1.5/×2 presets that compound
 * (story 399). Never at or below 0; a field left empty or not a number is marked invalid and
 * emits nothing, so a save can't log 0.1 g (story 368). It is a form control (story 458): an
 * invalid amount blocks its form's submit, and a form reset puts back `defaultValue`.
 *
 *   <amount-input unit="g" presets></amount-input>   .value = 150, .defaultValue = 150
 *
 * `unit` is a food base unit or `factor` (a scale, shown as ×). Emits `health:amount-change`.
 */
export class AmountInput extends HTMLElement {
    static formAssociated = true;
    static get observedAttributes() { return ['unit', 'presets', 'label']; }

    #internals: ElementInternals;

    private current = 1;
    private resetValue = 1;
    private readonly controls: readonly (HTMLInputElement | HTMLButtonElement)[];
    private readonly input: HTMLInputElement;

    constructor() {
        super();
        this.#internals = this.attachInternals();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        this.input = shadow.querySelector('.amount') as HTMLInputElement;
        this.controls = [this.input, ...shadow.querySelectorAll<HTMLButtonElement>('button')];

        shadow.querySelectorAll<HTMLButtonElement>('.step').forEach((b) => b.addEventListener('click', () => {
            this.commit(stepAmount(this.unit, this.typed() ?? this.current, Number(b.dataset.dir) as 1 | -1));
        }));
        shadow.querySelectorAll<HTMLButtonElement>('.preset').forEach((b) => b.addEventListener('click', () => {
            this.commit(applyPreset(this.typed() ?? this.current, Number(b.dataset.factor)));
        }));
        this.input.addEventListener('input', () => {
            const typed = this.typed();
            this.input.toggleAttribute('aria-invalid', typed === null);
            if (typed === null) {
                this.#internals.setFormValue(null);
                const [flags, message] = invalidity(this.input.value);
                this.#internals.setValidity(flags, message, this.input);
            } else {
                this.#internals.setFormValue(String(typed));
                this.#internals.setValidity({});
            }
            if (typed !== null && typed !== this.current) {
                this.current = typed;
                this.dispatchEvent(createAmountChangeEvent({ value: typed }));
            }
        });
        // The field sits in this shadow root, so it has no form owner and the browser's own
        // Enter-submits never reaches the form this control belongs to: submit it here, as a
        // native input would. Not the Enter that ends an IME composition (story 458).
        this.input.addEventListener('keydown', (e) => {
            if (e.key !== 'Enter' || e.isComposing) return;
            e.preventDefault();
            this.#internals.form?.requestSubmit();
        });
    }

    get unit(): AmountUnit {
        const u = this.getAttribute('unit');
        return u === 'ml' || u === 'piece' || u === 'factor' ? u : 'g';
    }

    /** The amount it holds. Like a native input's `value`, setting it leaves `defaultValue` alone. */
    get value(): number { return this.current; }
    set value(v: number) {
        this.current = checkAmount(v);
        this.render();
    }

    /** What a form reset puts back — a native input's `defaultValue`. */
    get defaultValue(): number { return this.resetValue; }
    set defaultValue(v: number) {
        this.resetValue = checkAmount(v);
    }

    // The constraint validation API every form control has. A control that wraps this one
    // (`<line-row>`) reads it to pass the validity up to its own form (`utils/validity.ts`).
    get form(): HTMLFormElement | null { return this.#internals.form; }
    get validity(): ValidityState { return this.#internals.validity; }
    get validationMessage(): string { return this.#internals.validationMessage; }
    checkValidity(): boolean { return this.#internals.checkValidity(); }
    reportValidity(): boolean { return this.#internals.reportValidity(); }
    /** The field the browser points at when the amount is invalid. */
    get validationAnchor(): HTMLElement { return this.input; }

    /** What is typed, when it is an amount above 0; `,` reads as a decimal point. */
    private typed(): number | null {
        const n = Number(this.input.value.trim().replace(',', '.'));
        return this.input.value.trim() !== '' && Number.isFinite(n) && n > 0 ? roundAmount(n) : null;
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    formResetCallback(): void {
        this.current = this.resetValue;
        this.render();
    }

    formDisabledCallback(disabled: boolean): void {
        for (const control of this.controls) {
            control.disabled = disabled;
        }
    }

    private commit(v: number): void {
        const changed = v !== this.current;
        this.current = v;
        this.render();
        if (changed) this.dispatchEvent(createAmountChangeEvent({ value: v }));
        // A step or preset rewrites the field (and may clear its invalid state), as a native
        // number input's spin buttons do: say so with `input`, so a control wrapping this one
        // re-reads the validity.
        this.dispatchEvent(new Event('input', { bubbles: true, composed: true }));
    }

    private render(): void {
        const shadow = this.shadowRoot!;
        this.input.value = String(this.current);
        this.#internals.setFormValue(String(this.current));
        this.#internals.setValidity({});
        this.input.removeAttribute('aria-invalid');
        const label = this.getAttribute('label');
        this.input.setAttribute('aria-label', label ?? 'Amount');
        const unitEl = shadow.querySelector('.unit') as HTMLElement;
        unitEl.textContent = this.unit === 'factor' ? '×' : unitLabel(this.unit);
        (shadow.querySelector('.presets') as HTMLElement).hidden = !this.hasAttribute('presets');
        for (const b of shadow.querySelectorAll<HTMLButtonElement>('.step')) {
            const word = b.dataset.dir === '1' ? 'More' : 'Less';
            b.setAttribute('aria-label', label ? `${word} ${label}` : word);
        }
    }
}

/**
 * Why typed text is not an amount, as the flag a native `<input type="number" min>` would set:
 * empty is `valueMissing`, not a number (`abc`) is `badInput`, 0 or below (`-2`) is `rangeUnderflow`.
 */
function invalidity(text: string): [ValidityStateFlags, string] {
    const t = text.trim();
    if (t === '') return [{ valueMissing: true }, 'Enter an amount.'];
    if (!Number.isFinite(Number(t.replace(',', '.')))) return [{ badInput: true }, 'Enter a number.'];
    return [{ rangeUnderflow: true }, 'The amount must be above 0.'];
}

function checkAmount(v: number): number {
    if (!Number.isFinite(v) || v <= 0) throw new Error(`amount-input: ${v} is not an amount above 0`);
    return roundAmount(v);
}

if (!customElements.get('amount-input')) {
    customElements.define('amount-input', AmountInput);
}
